{"content": "     1|// useStrategy.js
     2|// Production Planner: simulatore + greedy goal-oriented per raggiungere un target
     3|// di produzione giornaliera di metallo. Riusa al millimetro le formule di
     4|// MetalCalc.vue e i costi di PackCalc.vue.
     5|//
     6|// Modello di "stato simulato":
     7|//   {
     8|//     settings: { ecoSpeed, playerClass, rocktalEnhancement, allyClass,
     9|//                 plasma, geologist, staff, lfBonus },
    10|//     planets:  [{ name, pos, metal, crystal, deuterium, item, itemCustom,
    11|//                  magma, human, lifeform, crawlers, overload }, ...],
    12|//     pack:     { rateMet, rateCry, rateDeut, minLevel, lfRsrLabLevel },
    13|//     lfChoice: ['inherit'|'rocktal'|'humans'|'mecha', ...]  // per pianeta
    14|//   }
    15|//
    16|// Lo stato è una *copia indipendente* del profilo attivo: il planner non scrive
    17|// mai sul profilo, espone solo i risultati.
    18|
    19|import { OGAME_DB } from '../data/ogame_db';
    20|import { useOgameFormulas } from './useOgameFormulas';
    21|
    22|const { calcMineProduction, getPosMult, calcCrawlerCap, getBuildCostLF } = useOgameFormulas();
    23|
    24|// ───── Helpers di base ─────────────────────────────────────────────────────
    25|
    26|// Lifeform "effettivo" di un pianeta tenendo conto dell'override per pianeta.
    27|const effectiveLifeform = (planet, choice) => {
    28|    if (!choice || choice === 'inherit') return planet.lifeform || 'humans';
    29|    return choice;
    30|};
    31|
    32|// Costo cumulativo miniera/plasma (building/research classico) con sconto miner.
    33|// Replica la stessa logica di PackCalc.vue: factor^(i-1), arrotondamento per livello.
    34|// Sconto Centro Mineralogia: solo su metal_mine/crystal_mine/deuterium_synthesizer.
    35|const buildingCumulativeCost = (itemKey, fromLevel, toLevel, minLevel) => {
    36|    const itemData =
    37|        OGAME_DB.resources.items[itemKey] ||
    38|        OGAME_DB.facilities.items[itemKey] ||
    39|        OGAME_DB.research.items[itemKey];
    40|    if (!itemData) return [0, 0, 0];
    41|    const isMine = ['metal_mine', 'crystal_mine', 'deuterium_synthesizer'].includes(itemKey);
    42|    const discount = isMine ? Math.min(0.5, (parseInt(minLevel) || 0) * 0.005) : 0;
    43|    let m = 0, c = 0, d = 0;
    44|    for (let i = fromLevel + 1; i <= toLevel; i++) {
    45|        const factor = Math.pow(itemData.factor, i - 1);
    46|        let cm = Math.floor(itemData.cost[0] * factor);
    47|        let cc = Math.floor(itemData.cost[1] * factor);
    48|        let cd = Math.floor(itemData.cost[2] * factor);
    49|        if (discount > 0) {
    50|            cm = Math.floor(cm * (1 - discount));
    51|            cc = Math.floor(cc * (1 - discount));
    52|            cd = Math.floor(cd * (1 - discount));
    53|        }
    54|        m += cm; c += cc; d += cd;
    55|    }
    56|    return [m, c, d];
    57|};
    58|
    59|// Costo di un edificio LF (1006 = Fusione alta energia, 2006 = Fusione magmatica)
    60|// per i livelli da+1 → to. Usa il composable esistente.
    61|const lfBuildingCost = (lifeform, techId, fromLevel, toLevel, lfRsrLabLevel) => {
    62|    let catKey;
    63|    if (lifeform === 'humans') catKey = 'lf_humans';
    64|    else if (lifeform === 'rocktal') catKey = 'lf_rocktal';
    65|    else return [0, 0, 0]; // mecha/kaelesh: per ora nessun bonus metallo
    66|    const cat = OGAME_DB[catKey];
    67|    if (!cat) return [0, 0, 0];
    68|    return getBuildCostLF(String(techId), fromLevel, toLevel, cat.items, lfRsrLabLevel || 0, 0);
    69|};
    70|
    71|// Converte un triplo [m,c,d] in MSU (metallo-equivalente) usando i rate del pack-exchange.
    72|// rateMet / rateCry = quanti metallo per 1 cristallo (in valore).
    73|const toMSU = (cost, pack) => {
    74|    const rM = parseFloat(pack.rateMet) || 3;
    75|    const rC = parseFloat(pack.rateCry) || 2;
    76|    const rD = parseFloat(pack.rateDeut) || 1;
    77|    return cost[0] + cost[1] * (rM / rC) + cost[2] * (rM / rD);
    78|};
    79|
    80|// ───── Simulatore produzione (copia 1:1 di MetalCalc.vue) ──────────────────
    81|// Differenza: i crawler vengono SEMPRE saturati al cap (l'utente ha detto
    82|// "assumiamo che le persone abbiano già più crawler del necessario").
    83|const simulateDailyProduction = (state) => {
    84|    const { settings, planets, lfChoice } = state;
    85|    const collFactor = 1 + ((settings.rocktalEnhancement || 0) / 100);
    86|    const ecoSpeed = settings.ecoSpeed || 1;
    87|    const isCollector = settings.playerClass === 'collector';
    88|    let hourly = 0;
    89|
    90|    planets.forEach((p, idx) => {
    91|        const met = parseInt(p.metal) || 0;
    92|        const posMult = getPosMult(p.pos);
    93|        const natProd = Math.floor(30 * ecoSpeed * posMult);
    94|        const mineBase = calcMineProduction(met, ecoSpeed, posMult);
    95|
    96|        let totPerc = (settings.plasma || 0) * 1;
    97|        if (settings.geologist) totPerc += 10;
    98|        if (settings.staff) totPerc += 2;
    99|        if (isCollector) totPerc += 25 * collFactor;
   100|        if (settings.allyClass === 'trader') totPerc += 5;
   101|        totPerc += (parseInt(p.item) || 0) + (parseInt(p.itemCustom) || 0);
   102|
   103|        const lf = effectiveLifeform(p, lfChoice[idx]);
   104|        if (lf === 'rocktal') {
   105|            totPerc += (parseInt(p.magma) || 0) * 2;
   106|        } else if (lf === 'humans') {
   107|            totPerc += (parseInt(p.human) || 0) * 1.5;
   108|        }
   109|        totPerc += settings.lfBonus || 0;
   110|
   111|        // Crawler: SEMPRE al cap (per ipotesi di progetto)
   112|        const maxCraw = calcCrawlerCap(met, p.crystal, p.deuterium, isCollector, settings.geologist, settings.rocktalEnhancement);
   113|        const actCraw = maxCraw;
   114|        if (actCraw > 0) {
   115|            let mult = 0.02;
   116|            if (isCollector) {
   117|                mult *= (1 + (50 * collFactor) / 100);
   118|                if (p.overload) mult *= 1.5;
   119|            }
   120|            totPerc += Math.min(actCraw * mult, 50);
   121|        }
   122|
   123|        const bonusProd = Math.floor(mineBase * (totPerc / 100));
   124|        hourly += (natProd + mineBase + bonusProd);
   125|    });
   126|    return Math.floor(hourly * 24);
   127|};
