   129|// ───── Generatori di candidati ────────────────────────────────────────────
   130|// Un "candidato" è una funzione che, applicata su una copia dello stato, lo
   131|// trasforma di uno step. Ritorna {label, apply(state), cost: [m,c,d], meta}.
   132|
   133|const buildCandidates = (state, options) => {
   134|    const candidates = [];
   135|    const { settings, planets, pack, lfChoice } = state;
   136|    const { caps } = options;
   137|
   138|    // 1) Miniera di metallo +1 per ogni pianeta
   139|    if (options.includeMines) {
   140|        planets.forEach((p, idx) => {
   141|            const lvl = parseInt(p.metal) || 0;
   142|            const maxLvl = caps?.metalMine ?? Infinity;
   143|            if (lvl >= maxLvl) return;
   144|            const cost = buildingCumulativeCost('metal_mine', lvl, lvl + 1, pack.minLevel);
   145|            candidates.push({
   146|                type: 'metal_mine',
   147|                planetIdx: idx,
   148|                from: lvl,
   149|                to: lvl + 1,
   150|                cost,
   151|                apply: (s) => { s.planets[idx].metal = lvl + 1; }
   152|            });
   153|        });
   154|    }
   155|
   156|    // 2) Tecnologia Plasma +1 (globale)
   157|    if (options.includePlasma) {
   158|        const lvl = parseInt(settings.plasma) || 0;
   159|        const maxLvl = caps?.plasma ?? Infinity;
   160|        if (lvl < maxLvl) {
   161|            const cost = buildingCumulativeCost('plasma_technology', lvl, lvl + 1, pack.minLevel);
   162|            candidates.push({
   163|                type: 'plasma_technology',
   164|                from: lvl,
   165|                to: lvl + 1,
   166|                cost,
   167|                apply: (s) => { s.settings.plasma = lvl + 1; }
   168|            });
   169|        }
   170|    }
   171|
   172|    // 3) Edifici LF "produzione metallo" — solo per i pianeti che hanno
   173|    //    Rocktal o Humans come lifeform effettivo (incluso override).
   174|    if (options.includeLf) {
   175|        planets.forEach((p, idx) => {
   176|            const lf = effectiveLifeform(p, lfChoice[idx]);
   177|            if (lf === 'rocktal') {
   178|                const lvl = parseInt(p.magma) || 0;
   179|                const maxLvl = caps?.lfBuilding ?? Infinity;
   180|                if (lvl >= maxLvl) return;
   181|                const cost = lfBuildingCost('rocktal', 2006, lvl, lvl + 1, pack.lfRsrLabLevel);
   182|                candidates.push({
   183|                    type: 'lf_magma',
   184|                    planetIdx: idx,
