   191|                const lvl = parseInt(p.human) || 0;
   192|                const maxLvl = caps?.lfBuilding ?? Infinity;
   193|                if (lvl >= maxLvl) return;
   194|                const cost = lfBuildingCost('humans', 1006, lvl, lvl + 1, pack.lfRsrLabLevel);
   195|                candidates.push({
   196|                    type: 'lf_human',
   197|                    planetIdx: idx,
   198|                    from: lvl,
   199|                    to: lvl + 1,
   200|                    cost,
   201|                    apply: (s) => { s.planets[idx].human = lvl + 1; }
   202|                });
   203|            }
   204|        });
