   210|// ───── Greedy planner ─────────────────────────────────────────────────────
   211|//
   212|// Ad ogni step:
   213|//   - calcola produzione corrente (= packValue dello step)
   214|//   - per ogni candidato: applica su stato temp, calcola Δprod, costo in MSU,
   215|//     pacchetti necessari (costo MSU / packValue), score = Δprod / pacchetti.
   216|//   - se nessun candidato ha Δprod > 0, ferma.
   217|//   - prende il candidato col miglior score, lo applica davvero, registra
   218|//     uno step nella roadmap e ricalcola il packValue.
   219|
   220|export const runPlanner = (initialState, options = {}) => {
   221|    const cfg = {
   222|        maxSteps: 200,
   223|        includeMines: true,
   224|        includePlasma: true,
   225|        includeLf: true,
   226|        minScoreThreshold: 0, // pacchetti / metallo / giorno minimo (0 = nessun filtro)
   227|        caps: { metalMine: Infinity, plasma: Infinity, lfBuilding: Infinity },
   228|        ...options
   229|    };
   230|
   231|    // Deep-clone difensivo: il planner deve essere puro.
   232|    const state = JSON.parse(JSON.stringify(initialState));
   233|    const steps = [];
   234|
   235|    const initialProd = simulateDailyProduction(state);
   236|    let currentProd = initialProd;
   237|    let cumulativeMSU = 0;
   238|    let cumulativePacks = 0;
   239|
   240|    const target = parseInt(cfg.target) || 0;
   241|    if (target <= initialProd) {
   242|        return {
   243|            initialProd,
   244|            finalProd: initialProd,
   245|            steps,
   246|            cumulativeMSU: 0,
   247|            cumulativePacks: 0,
   248|            reachedTarget: true,
   249|            stoppedReason: 'already_at_target'
   250|        };
   251|    }
   252|
   253|    let stoppedReason = 'max_steps';
   254|
   255|    for (let step = 0; step < cfg.maxSteps; step++) {
   256|        if (currentProd >= target) {
   257|            stoppedReason = 'target_reached';
   258|            break;
   259|        }
   260|
   261|        // packValue dello step corrente = produzione giornaliera attuale
   262|        const packValue = Math.max(1, currentProd);
   263|
   264|        const candidates = buildCandidates(state, cfg);
   265|        if (candidates.length === 0) {
   266|            stoppedReason = 'no_candidates';
   267|            break;
   268|        }
   269|
   270|        let best = null;
   271|        for (const cand of candidates) {
   272|            // Simula su una *copia* dello stato
   273|            const tempState = JSON.parse(JSON.stringify(state));
   274|            cand.apply(tempState);
   275|            const newProd = simulateDailyProduction(tempState);
   276|            const deltaProd = newProd - currentProd;
   277|            if (deltaProd <= 0) continue;
   278|            const costMSU = toMSU(cand.cost, state.pack);
   279|            if (costMSU <= 0) continue;
   280|            const packs = costMSU / packValue;
   281|            const score = deltaProd / packs; // metallo/giorno guadagnato per pacchetto
   282|
   283|            if (!best || score > best.score) {
   284|                best = { cand, deltaProd, costMSU, packs, score, newProd };
   285|            }
   286|        }
   287|
   288|        if (!best) {
   289|            stoppedReason = 'no_positive_delta';
   290|            break;
   291|        }
   292|        if (cfg.minScoreThreshold > 0 && best.score < cfg.minScoreThreshold) {
   293|            stoppedReason = 'score_below_threshold';
   294|            break;
   295|        }
   296|
   297|        // Applica per davvero
   298|        best.cand.apply(state);
   299|        cumulativeMSU += best.costMSU;
   300|        cumulativePacks += best.packs;
   301|        currentProd = best.newProd;
   302|
   303|        steps.push({
   304|            n: step + 1,
   305|            type: best.cand.type,
   306|            planetIdx: best.cand.planetIdx ?? null,
   307|            planetName: best.cand.planetIdx != null ? (state.planets[best.cand.planetIdx].name || `#${best.cand.planetIdx + 1}`) : null,
   308|            from: best.cand.from,
   309|            to: best.cand.to,
   310|            cost: best.cand.cost,
   311|            costMSU: best.costMSU,
   312|            packs: best.packs,
   313|            packValue,
   314|            deltaProd: best.deltaProd,
   315|            cumulativeProd: currentProd,
   316|            cumulativeMSU,
   317|            cumulativePacks,
   318|            score: best.score
   319|        });
   320|    }
   321|
   322|    return {
   323|        initialProd,
   324|        finalProd: currentProd,
   325|        steps,
   326|        cumulativeMSU,
   327|        cumulativePacks,
   328|        reachedTarget: currentProd >= target,
   329|        stoppedReason
   330|    };
   331|};
