   333|// ───── Conversione MO/€ identica a PackCalc.vue ───────────────────────────
   334|// Dato il totale di pacchetti necessari, calcola il numero di MO totali e il
   335|// bundle più economico in €. Estratto dalla logica `euroOptimization` di PackCalc.
   336|//
   337|// shop: { shopDiscount: %, moBonus: %, paymentBonus: bool, smartRounding: bool }
   338|const basePacks = [
   339|    { cost: 200, amount: 5100000 },
   340|    { cost: 100, amount: 2525000 },
   341|    { cost: 50, amount: 1140000 },
   342|    { cost: 25, amount: 480000 },
   343|    { cost: 10, amount: 150000 },
   344|    { cost: 5, amount: 60000 }
   345|];
   346|
   347|export const computeEuroCost = (packsNeeded, shop = {}) => {
   348|    const basePackPrice = 60000;
   349|    const discountFactor = 1 - ((parseInt(shop.shopDiscount) || 0) / 100);
   350|    const moPerPack = basePackPrice * discountFactor;
   351|    const totalMO = Math.ceil(packsNeeded) * moPerPack;
   352|    if (totalMO <= 0) return { totalMO: 0, totalEuro: 0, packList: [] };
   353|
   354|    const bonusMult = 1 + ((parseInt(shop.moBonus) || 0) / 100);
   355|    const hasPaymentBonus = !!shop.paymentBonus;
   356|    const currentPacks = basePacks.map(p => {
   357|        let amt = p.amount;
   358|        if (hasPaymentBonus) amt += (p.cost * 1000);
   359|        return { cost: p.cost, amount: Math.floor(amt * bonusMult) };
   360|    });
   361|
   362|    const findBest = (target, packs) => {
   363|        if (target <= 0) return { totalCost: 0, packList: [] };
   364|        const currentPack = packs[0];
   365|        const countA = Math.ceil(target / currentPack.amount);
   366|        const costA = countA * currentPack.cost;
   367|        if (packs.length === 1) return { totalCost: costA, packList: [{ count: countA, pack: currentPack }] };
   368|        const countB = Math.floor(target / currentPack.amount);
   369|        const sub = findBest(target - countB * currentPack.amount, packs.slice(1));
   370|        const costB = countB * currentPack.cost + sub.totalCost;
   371|        if (costA <= costB) return { totalCost: costA, packList: [{ count: countA, pack: currentPack }] };
   372|        const listB = [...sub.packList];
   373|        if (countB > 0) listB.push({ count: countB, pack: currentPack });
   374|        return { totalCost: costB, packList: listB };
   375|    };
   376|
   377|    const res = findBest(totalMO, currentPacks);
   378|    res.packList.sort((a, b) => b.pack.cost - a.pack.cost);
   379|    return { totalMO, totalEuro: res.totalCost, packList: res.packList };
   380|};
